script:
pm.test("Response has a 200 status code", function () {
    pm.response.to.have.status(200);
});

pm.test("Response has the correct Content-Type header", function () {
    pm.response.to.have.header("Content-Type", "application/json; charset=utf-8");
});

pm.test("Response body is an array", function () {
    pm.expect(pm.response.json()).to.be.an("array");
});

pm.test("Each item in the response has the expected structure", function () {
    const responseBody = pm.response.json();
    responseBody.forEach(function (item) {
        pm.expect(item).to.have.property("id");
        pm.expect(item).to.have.property("fullName");
        pm.expect(item).to.have.property("email");
        pm.expect(item).to.have.property("studentCourses");
    });
});
